        {0, 0, 0, 0, -4, 0, 0, 0}
    };

    public static void main(String[] args) {
        int[][] nlatTable = new int[8][8];

        for (int a = 0; a < 8; a++) {
            for (int b = 0; b < 8; b++) {
                int latValue = lat(inputVectors, outputVectors, a, b);
                nlatTable[a][b] = latValue - 4;
