import sys
from collections import deque

class Node:
    def __init__(self):
        self.left = None
        self.right = None

def build_tree(level_order):
    if not level_order or level_order[0] == 0:
        return None
    root = Node()
    q = deque()
    q.append(root)
    index = 1
    while q and index < len(level_order):
        current = q.popleft()
        if index < len(level_order):
            if level_order[index] == 1:
                current.left = Node()
                q.append(current.left)
            else:
                current.left = None
            index += 1
        else:
            break
        if index < len(level_order):
            if level_order[index] == 1:
                current.right = Node()
                q.append(current.right)
            else:
                current.right = None
            index += 1
        else:
            break
    return root

def compute_min_phones(root):
    INF = float('inf')

    def dfs(node):
        if not node:
            return (INF, INF, INF)

        left = dfs(node.left)
        right = dfs(node.right)

        min_left_1_2 = min(left[1], left[2]) if node.left else INF
        min_right_1_2 = min(right[1], right[2]) if node.right else INF
        min_left_all = min(left) if node.left else INF
        min_right_all = min(right) if node.right else INF

        dp0 = 0
        if node.left:
            dp0 += min_left_1_2
        if node.right:
            dp0 += min_right_1_2

        sum_min = 0
        min_delta = INF
        has_children = False

        if node.left:
            has_children = True
            sum_min += min_left_1_2
            delta = left[2] - min_left_1_2
            if delta < min_delta:
                min_delta = delta

        if node.right:
            has_children = True
            sum_min += min_right_1_2
            delta = right[2] - min_right_1_2
            if delta < min_delta:
                min_delta = delta

        dp1 = INF if not has_children or min_delta == INF else sum_min + min_delta

        dp2 = 1
        if node.left:
            dp2 += min_left_all
        if node.right:
            dp2 += min_right_all

        return (dp0, dp1, dp2)

    if not root:
        return 0
    dp_root = dfs(root)
    ans = min(dp_root[1], dp_root[2])
    return ans if ans != INF else 0

def main():
    n = int(sys.stdin.readline())
    level_order = list(map(int, sys.stdin.readline().split()))
    root = build_tree(level_order)
    print(compute_min_phones(root))

if __name__ == "__main__":
    main()

