% Read panel data from file
function [panels, points] = read_panels(filename)
    points = dlmread(filename);
    n = size(points, 1);
    panels = [];
    for i = 1:n
        x1 = points(i, 1);
        y1 = points(i, 2);
        x2 = points(mod(i, n)+1, 1);
        y2 = points(mod(i, n)+1, 2);
        panels(end+1, :) = [x1, y1, x2, y2];
    end
end

% Compute control points, normals, and tangents
function [midpoints, normals, panel_lengths, tangents] = compute_control_points(panels)
    n = size(panels, 1);
    midpoints = zeros(n, 2);
    normals = zeros(n, 2);
    panel_lengths = zeros(n, 1);
    tangents = zeros(n, 2);
    for j = 1:n
        x_a = panels(j, 1);
        y_a = panels(j, 2);
        x_b = panels(j, 3);
        y_b = panels(j, 4);
        xm = (x_a + x_b) / 2;
        ym = (y_a + y_b) / 2;
        midpoints(j, :) = [xm, ym];
        dx = x_b - x_a;
        dy = y_b - y_a;
        L = sqrt(dx^2 + dy^2);
        panel_lengths(j) = L;
        tx = dx / L;
        ty = dy / L;
        tangents(j, :) = [tx, ty];
        nx = dy / L;
        ny = -dx / L;
        normals(j, :) = [nx, ny];
    end
end

% Compute influence matrix using 3-point Gauss quadrature
function A = compute_influence_matrix(midpoints, normals, panels, panel_lengths)
    n = size(panels, 1);
    A = zeros(n);
    gauss_points = [-sqrt(3/5), 5/9;
                     0.0, 8/9;
                     sqrt(3/5), 5/9];
    for i = 1:n
        x_i = midpoints(i, 1);
        y_i = midpoints(i, 2);
        nx_i = normals(i, 1);
        ny_i = normals(i, 2);
        for j = 1:n
            if i == j
                A(i, j) = 0.5;
            else
                x_a_j = panels(j, 1);
                y_a_j = panels(j, 2);
                x_b_j = panels(j, 3);
                y_b_j = panels(j, 4);
                L_j = panel_lengths(j);
                sum_integral = 0.0;
                for k = 1:size(gauss_points, 1)
                    s = gauss_points(k, 1);
                    w = gauss_points(k, 2);
                    x_jk = x_a_j + (x_b_j - x_a_j) * (s + 1) / 2;
                    y_jk = y_a_j + (y_b_j - y_a_j) * (s + 1) / 2;
                    dx = x_i - x_jk;
                    dy = y_i - y_jk;
                    dist_sq = dx^2 + dy^2;
                    if dist_sq < 1e-12
                        contrib = 0.0;
                    else
                        dot_product = dx * nx_i + dy * ny_i;
                        integrand = dot_product / dist_sq;
                        contrib = integrand * w;
                    end
                    sum_integral = sum_integral + contrib;
                end
                integral = sum_integral * (L_j / 2);
                A(i, j) = integral / (2 * pi);
            end
        end
    end
end

% Compute RHS of the system
function rhs = compute_rhs(alpha_deg, Vinf, normals)
    alpha_rad = deg2rad(alpha_deg);
    n = size(normals, 1);
    rhs = zeros(n, 1);
    for i = 1:n
        nx = normals(i, 1);
        ny = normals(i, 2);
        Vn = Vinf * (cos(alpha_rad) * nx + sin(alpha_rad) * ny);
        rhs(i) = -Vn;
    end
end

% Compute pressure coefficients
function [cp, theta, cp_analytical] = compute_cp(Vinf, alpha_deg, sigma, panels, midpoints, normals, tangents, panel_lengths)
    n = size(panels, 1);
    cp = zeros(n, 1);
    theta = [];
    cp_analytical = [];

    % Try to compute angles for analytical solution (circular cylinder)
    try
        theta = atan2(midpoints(:,2), midpoints(:,1));
        cp_analytical = 1.0 - 4.0 * sin(theta).^2;
    catch
        theta = [];
        cp_analytical = [];
    end

    for i = 1:n
        x_i = midpoints(i, 1);
        y_i = midpoints(i, 2);
        tx = tangents(i, 1);
        ty = tangents(i, 2);
        u_ind = 0.0;
        v_ind = 0.0;
        for j = 1:n
            x_a_j = panels(j, 1);
            y_a_j = panels(j, 2);
            x_b_j = panels(j, 3);
            y_b_j = panels(j, 4);
            L_j = panel_lengths(j);
            sigma_j = sigma(j);
            for k = 1:3
                s = gauss_points(k, 1);
                w = gauss_points(k, 2);
                x_jk = x_a_j + (x_b_j - x_a_j) * (s + 1) / 2;
                y_jk = y_a_j + (y_b_j - y_a_j) * (s + 1) / 2;
                dx = x_i - x_jk;
                dy = y_i - y_jk;
                dist_sq = dx^2 + dy^2;
                if dist_sq < 1e-12
                    u_contribution = 0.0;
                    v_contribution = 0.0;
                else
                    factor = sigma_j * w * (L_j / 2) / (2 * pi * dist_sq);
                    u_contribution = dx * factor;
                    v_contribution = dy * factor;
                end
                u_ind = u_ind + u_contribution;
                v_ind = v_ind + v_contribution;
            end
        end
        u_fs = Vinf * cos(deg2rad(alpha_deg));
        v_fs = Vinf * sin(deg2rad(alpha_deg));
        u_total = u_ind + u_fs;
        v_total = v_ind + v_fs;
        Vt = u_total * tx + v_total * ty;
        cp(i) = 1.0 - (Vt / Vinf)^2;
    end
end

% Compute lift coefficient using Kutta-Joukowski theorem
function Cl = compute_cl(Vinf, sigma, panels)
    Cl = 0.0; % Source-only method yields zero lift
end
