% Helper functions

function panels = create_panels(points)
    n = size(points, 1);
    panels = cell(n, 1);
    for i = 1:n
        x1 = points(i, 1);
        y1 = points(i, 2);
        x2 = points(mod(i, n) + 1, 1);
        y2 = points(mod(i, n) + 1, 2);
        panels{i} = [x1, y1, x2, y2];
    end
end

function [midpoints, normals, panel_lengths, tangents] = compute_control_points(panels)
    n = length(panels);
    midpoints = zeros(n, 2);
    normals = zeros(n, 2);
    panel_lengths = zeros(n, 1);
    tangents = zeros(n, 2);

    for j = 1:n
        panel = panels{j};
        x1 = panel(1);
        y1 = panel(2);
        x2 = panel(3);
        y2 = panel(4);

        % Midpoint
        xm = (x1 + x2) / 2;
        ym = (y1 + y2) / 2;
        midpoints(j, :) = [xm, ym];

        % Panel vector
        dx = x2 - x1;
        dy = y2 - y1;
        L = sqrt(dx^2 + dy^2);
        panel_lengths(j) = L;

        % Tangent vector
        tx = dx / L;
        ty = dy / L;
        tangents(j, :) = [tx, ty];

        % Normal vector
        nx = dy / L;
        ny = -dx / L;
        normals(j, :) = [nx, ny];
    end
end

function A = compute_influence_matrix(midpoints, normals, panels, panel_lengths)
    n = length(panels);
    A = zeros(n + 1);

    for i = 1:n
        for j = 1:n
            A(i, j) = influence_coefficients(panels{i}, panels{j}, midpoints(i, :), normals(i, :), false);
            A(i, n + 1) = A(i, n + 1) + influence_coefficients(panels{i}, panels{j}, midpoints(i, :), normals(i, :), true);
        end
    end

    % Kutta condition: gamma_1 + gamma_n = 0
    A(n + 1, 1) = 1;
    A(n + 1, n) = 1;
    A(n + 1, n + 1) = 0;
end

function rhs = compute_rhs(alpha_deg, Vinf, normals)
    alpha = deg2rad(alpha_deg);
    n = size(normals, 1);
    rhs = zeros(n + 1, 1);

    for i = 1:n
        nx = normals(i, 1);
        ny = normals(i, 2);
        Vn = Vinf * (cos(alpha) * nx + sin(alpha) * ny);
        rhs(i) = -Vn;
    end
end

function cp = influence_coefficients(panel_i, panel_j, midpoint_i, normal_i, is_vortex)
    x1j = panel_j(1);
    y1j = panel_j(2);
    x2j = panel_j(3);
    y2j = panel_j(4);
    x_i = midpoint_i(1);
    y_i = midpoint_i(2);
    nx_i = normal_i(1);
    ny_i = normal_i(2);

    % Gauss quadrature points and weights
    gauss_points = [-sqrt(3/5), 5/9; 0.0, 8/9; sqrt(3/5), 5/9];
    integral = 0;

    for k = 1:size(gauss_points, 1)
        s = gauss_points(k, 1);
        w = gauss_points(k, 2);

        % Position on panel j
        x_jk = x1j + (x2j - x1j) * (s + 1) / 2;
        y_jk = y1j + (y2j - y1j) * (s + 1) / 2;

        % Distance from point i to current point on panel j
        dx = x_i - x_jk;
        dy = y_i - y_jk;
        dist_sq = dx^2 + dy^2;

        if dist_sq < 1e-12
            continue;
        end

        if is_vortex
            % Vortex influence
            contrib = (dy * nx_i - dx * ny_i) / dist_sq * w;
        else
            % Source influence
            contrib = (dx * nx_i + dy * ny_i) / dist_sq * w;
        end

        integral = integral + contrib;
    end

    cp = integral / (2 * pi);
end

function [cp, theta, cp_analytical] = compute_pressure_coefficients(Vinf, alpha_deg, sigma, gamma, panels, midpoints, normals, tangents, panel_lengths)
    n = length(panels);
    cp = zeros(n, 1);
    theta = [];
    cp_analytical = [];

    % Try to compute angles for analytical solution (circular cylinder)
    try
        theta = atan2(midpoints(:, 2), midpoints(:, 1));
        cp_analytical = 1.0 - 4.0 * sin(theta).^2;
    catch
        theta = [];
        cp_analytical = [];
    end

    alpha = deg2rad(alpha_deg);
    u_fs = Vinf * cos(alpha);
    v_fs = Vinf * sin(alpha);

    for i = 1:n
        xi = midpoints(i, 1);
        yi = midpoints(i, 2);
        tx = tangents(i, 1);
        ty = tangents(i, 2);

        u_ind = 0;
        v_ind = 0;

        for j = 1:n
            panel_j = panels{j};
            x1j = panel_j(1);
            y1j = panel_j(2);
            x2j = panel_j(3);
            y2j = panel_j(4);
            Lj = panel_lengths(j);

            % Source contribution
            for k = 1:3
                s = [-sqrt(3/5), 0, sqrt(3/5)];
                w = [5/9, 8/9, 5/9];

                % Position on panel j
                xjk = x1j + (x2j - x1j) * (s(k) + 1) / 2;
                yjk = y1j + (y2j - y1j) * (s(k) + 1) / 2;

                % Distance from point i to current point on panel j
                dx = xi - xjk;
                dy = yi - yjk;
                dist_sq = dx^2 + dy^2;

                if dist_sq < 1e-12
                    continue;
                end

                % Source contribution
                factor = sigma(j) * w(k) * (Lj / 2) / (2 * pi * dist_sq);
                u_ind = u_ind + dx * factor;
                v_ind = v_ind + dy * factor;
            end

            % Vortex contribution
            for k = 1:3
                s = [-sqrt(3/5), 0, sqrt(3/5)];
                w = [5/9, 8/9, 5/9];

                % Position on panel j
                xjk = x1j + (x2j - x1j) * (s(k) + 1) / 2;
                yjk = y1j + (y2j - y1j) * (s(k) + 1) / 2;

                % Distance from point i to current point on panel j
                dx = xi - xjk;
                dy = yi - yjk;
                dist_sq = dx^2 + dy^2;

                if dist_sq < 1e-12
                    continue;
                end

                % Vortex contribution
                factor = gamma * w(k) * (Lj / 2) / (2 * pi * dist_sq);
                u_ind = u_ind - dy * factor;
                v_ind = v_ind + dx * factor;
            end
        end

        % Total velocity components
        u_total = u_ind + u_fs;
        v_total = v_ind + v_fs;

        % Tangential velocity
        Vt = u_total * tx + v_total * ty;

        % Pressure coefficient
        cp(i) = 1.0 - (Vt / Vinf)^2;
    end
end

function Cl = compute_cl(Vinf, gamma, panel_lengths, chord)
    Gamma = gamma * sum(panel_lengths);
    Cl = (2 * Gamma) / (Vinf * chord);
end

function [panel_numbers, max_errors] = perform_accuracy_check()
