const fs = require('fs/promises');
const sharp = require('sharp');

async function adjustWatermarkOpacity(watermarkBuffer, width, height, opacity) {
  const data = await sharp(watermarkBuffer)
    .resize(width, height)
    .ensureAlpha()
    .toFormat('raw')
    .toBuffer();

  const pixels = new Uint8Array(data);
  for (let i = 3; i < pixels.length; i += 4) {
    pixels[i] = Math.round(pixels[i] * opacity);
  }

  return sharp(pixels, {
    raw: {
      width, height, channels: 4
    }
  }).toFormat('png').toBuffer();
}

async function calculateVariance(imageBuffer, x, y, width, height) {
  try {
    const data = await sharp(imageBuffer)
      .extract({ left: x, top: y, width, height })
      .grayscale()
      .blur(2)  // Reduce noise with Gaussian blur
      .resize(16, 16, { fit: 'inside' })  // Downscale ROI for efficient computation
      .toBuffer({ raw: true });

    const pixels = new Uint8Array(data);
    const count = pixels.length;
    let sum = 0;
    for (let p of pixels) sum += p;
    const mean = sum / count;
    let variance = 0;
    for (let p of pixels) variance += Math.pow(p - mean, 2);
    return variance / count;
  } catch (err) {
    // Return high variance for problematic ROIs
    return Number.MAX_SAFE_INTEGER;
  }
}

async function addWatermarkToImage(imagePath, watermarkPath, outputImagePath, options = {}) {
  const {
    watermarkOpacity = 0.5,
    watermarkRatio = 0.2
  } = options;

  // Validate watermark ratio
  if (watermarkRatio <= 0 || watermarkRatio > 1) {
    throw new Error("watermarkRatio must be between 0 and 1");
  }

  // Read original image
  const image = sharp(imagePath);
  const metadata = await image.metadata();
  const { width: originalWidth, height: originalHeight } = metadata;

  // Calculate watermark dimensions
  const watermarkWidth = Math.round(originalWidth * watermarkRatio);
  const watermarkHeight = Math.round(originalHeight * watermarkRatio);

  // Read and process watermark
  const watermarkData = await fs.readFile(watermarkPath);
  const processedWatermark = await adjustWatermarkOpacity(
    watermarkData, watermarkWidth, watermarkHeight, watermarkOpacity
  );

  // Define corners with bounds checking
  const corners = {
    'top-left':     { x: 0, y: 0 },
    'top-right':    { x: originalWidth - watermarkWidth, y: 0 },
    'bottom-left':  { x: 0, y: originalHeight - watermarkHeight },
    'bottom-right': { x: originalWidth - watermarkWidth, y: originalHeight - watermarkHeight }
  };

  // Find best corner
  let bestCorner = 'top-left';
  let minVariance = Infinity;

  const imageBuffer = await image.toBuffer();

  const validCorners = Object.entries(corners).filter(([_, pos]) => 
    pos.x >= 0 && pos.y >= 0
  );

  // Analyze each valid corner
  for (const [name, pos] of validCorners) {
    const variance = await calculateVariance(
      imageBuffer, pos.x, pos.y, watermarkWidth, watermarkHeight
    );

    if (variance < minVariance) {
      minVariance = variance;
      bestCorner = name;
    }
  }

  // Composite watermark
  const { x, y } = corners[bestCorner];

  await sharp(imageBuffer)
    .composite([{
      input: processedWatermark,
      left: x,
      top: y,
      blend: 'over'
    }])
    .toFile(outputImagePath);

  return outputImagePath;
}

