function [publicKey, privateKey] = generateRSAKeys(keySize)
    if nargin == 0 || isempty(keySize)
        keySize = 2048; % Default key size
    end

    if keySize < 1024
        error('Key size must be at least 1024 bits for security');
    end

    % Generate large primes
    certainty = 100; % Certainty level for primality test
    [p, q] = generateLargePrimes(keySize/2, certainty);
    n = str2double(p.multiply(q).toString());

    % Compute φ(n)
    phi = str2double(p.subtract(BigInteger('1')).multiply(q.subtract(BigInteger('1'))).toString());

    % Choose public exponent e
    e_candidates = [65537, 3, 17, 257];
    e = [];
    for i = 1:length(e_candidates)
        if gcdJava(e_candidates(i), phi) == 1
            e = e_candidates(i);
            break;
        end
    end

    if isempty(e)
        error('No suitable public exponent found');
    end

    % Compute private exponent d
    d = modInverse(e, phi);

    publicKey = [e, n];
    privateKey = [d, n];
end

