import re
import random
import time
import requests
from bs4 import BeautifulSoup
from flask import Flask, request, jsonify
from flask_cors import CORS

app = Flask(__name__)
CORS(app, origins=["*"])  # Adjust to your Square.com domain in production

# Ethical scraping configuration
USER_AGENT = "SquareRecipeSpellBot/1.0"
REQUEST_DELAY = 2  # Seconds between requests


def extract_ingredients(recipe_text: str) -> List[str]:
    """Robust ingredient extraction with multiple parsing strategies"""
    ingredients = []
    lines = [line.strip().lower() for line in recipe_text.split('\n') if line.strip()]
    in_ingredients = False

    # Common ingredient patterns
    quantity_patterns = [r'\d+[\d\/\.]*', r'\d+"]
    prep_words = ['chopped', 'diced', 'sliced', 'minced', 'grated', 'to taste', 
                 'teaspoon', 'tablespoon', 'cup', 'cups', 'oz', 'pound', 'grams']

    for line in lines:
        # Sanitize input to prevent injection attacks
        line = re.sub(r'[\$\^\.\*\+\?\{\}\$\|\\]', '', line)

        if any(keyword in line for keyword in ['ingredients', 'ingredient']):
            in_ingredients = True
            continue

        if not in_ingredients:
            continue

        if any(keyword in line for keyword in ['instructions', 'method', 'directions']):
            break

        # Remove quantities and preparation notes
        ingredient = line
        for pattern in quantity_patterns:
            ingredient = re.split(pattern, ingredient, 1)[-1]

        for word in prep_words:
            ingredient = re.split(r'\b' + word + r'\b', ingredient, 1, flags=re.IGNORECASE)[0]

        ingredient = re.sub(r'[,$$]', '', ingredient).strip()

        if len(ingredient) > 2:
            ingredients.append(ingredient)

    return ingredients

def get_magical_properties(ingredient: str) -> Dict[str, List[str]]:
    """Ethical web scraping for magical properties"""
    try:
        headers = {'User-Agent': USER_AGENT}
        search_url = f"https://www.google.com/search?q={ingredient}+magical+properties"

        time.sleep(REQUEST_DELAY)
        response = requests.get(search_url, headers=headers, timeout=5)
        response.raise_for_status()

        soup = BeautifulSoup(response.text, 'html.parser')
        effects = {}

        # Process top 2 search results
        for result in soup.find_all('div', class_='g')[:2]:
            link = result.find('a', href=True)
            if not link:
                continue

            time.sleep(REQUEST_DELAY)
            page_response = requests.get(link['href'], timeout=5)
            page_response.raise_for_status()

            page_text = BeautifulSoup(page_response.text, 'html.parser').get_text().lower()

            # Common magical categories
            categories = ['protection', 'love', 'healing', 'prosperity', 'wisdom', 'energy', 'cleansing']
            for category in categories:
                if f"{ingredient} {category}" in page_text or f"{category} {ingredient}" in page_text:
                    sentences = re.split(r'[.!?]', page_text)
                    relevant = [s for s in sentences if ingredient in s and category in s]

                    if relevant:
                        effects.setdefault(category, [])
                        effects[category].extend([s.strip() for s in relevant[:1]])

        return effects or {ingredient[0].lower(): [f"hold secrets of {ingredient}"]}

    except Exception as e:
        return {ingredient[0].lower(): [f"hold secrets of {ingredient}"]}

def generate_spell(ingredients: List[str]) -> str:
    """Generate coherent spell with thematic consistency"""
    if not ingredients:
        return "No spell can be woven without ingredients!"

    # Collect all effects
    all_effects = []
    for ingredient in ingredients:
        effects = get_magical_properties(ingredient)
        for category, effect_list in effects.items():
            for effect in effect_list:
                all_effects.append({
                    'ingredient': ingredient,
                    'category': category,
                    'effect': effect
                })

    # Group by category and determine primary theme
    effects_by_category = {}
    for effect in all_effects:
        effects_by_category.setdefault(effect['category'], []).append(effect)

    sorted_categories = sorted(
        effects_by_category.items(), 
        key=lambda x: len(x[1]), 
        reverse=True
    )

    # Create spell structure
    spell_lines = []
    primary_theme = sorted_categories[0][0] if sorted_categories else 'mystery'
    spell_lines.append(f"=== {primary_theme.title()} Spell of Ingredients ===\n")

    # Invocation
    spell_lines.append(random.choice([
        "By the power of nature's bounty,",
        "With these sacred ingredients,",
        "Through the magic of creation,"
    ]))

    # Spell components
    for category, effects_list in sorted_categories[:3]:
        if effects_list:
            effect = random.choice(effects_list)
            spell_lines.append(
                f"Let the {effect['ingredient']} {effect['effect'].strip()},"
            )

    # Closing
    spell_lines.append("\nThus is the spell woven, by nature's design.")
    return "\n".join(spell_lines)

@app.route('/generate-spell', methods=['POST'])
def handle_spell_generation():
    """API endpoint for recipe spell generation"""
    try:
        data = request.get_json()
        recipe_text = data.get('recipe_text', '')

        ingredients = extract_ingredients(recipe_text)
        spell = generate_spell(ingredients)

        return jsonify({
            'spell': spell,
            'ingredients': ingredients,
            'status': 'success'
        })

    except Exception as e:
        return jsonify({
            'error': str(e),
            'status': 'error'
        }), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
